  final PestTaskTest.Fake base=new PestTaskTest.Fake();List<PestPlot> sent=new ArrayList<>();PestTrapObservation traps=PestTrapObservation.parse(List.of("Full Traps: #7"));List<PestTrapTarget> loaded=List.of();boolean known=true;MenuSnapshot menu;int opens,clicks,closes;
